-- Gold Query
SELECT t2.name, COUNT(t1.id) FROM Match AS t1 INNER JOIN League AS t2 ON t1.league_id = t2.id GROUP BY t2.name ORDER BY COUNT(t1.id) DESC, t2.name NULLS LAST LIMIT 1;

/*
Gold Result:
('Ryan Munoz', 4)
*/

-- Prediction Query
SELECT L.name, COUNT(M.id) AS total_matches FROM League AS L JOIN Match AS M ON L.id = M.league_id GROUP BY L.id ORDER BY total_matches DESC, L.name NULLS LAST LIMIT 1;

/*
Prediction Result:
('Ryan Munoz', 1)
